"""Table status and waitlist for TableSync (matches the pilot plan)."""
from collections import deque

class TableBoard:
    def __init__(self, tables):
        self.status = {t: "open" for t in tables}  # open | seated | dirty
        self.waitlist = deque()

    def add_party(self, name, size):
        self.waitlist.append({"name": name, "size": size})
        return len(self.waitlist)

    def seat_next(self, table_size):
        for i, p in enumerate(self.waitlist):
            if p["size"] <= table_size:
                for t, s in self.status.items():
                    if s == "open":
                        self.status[t] = "seated"
                        del self.waitlist[i]
                        return t, p["name"]
        return None

    def turn(self, table):
        self.status[table] = "dirty"

    def clean(self, table):
        self.status[table] = "open"

if __name__ == "__main__":
    b = TableBoard([1, 2, 3])
    b.add_party("Lee", 2)
    b.add_party("Ortiz", 4)
    print(b.seat_next(2), b.status)
